import fs from 'node:fs'
import path from 'node:path'

/** Invalid user IDs and unsafe snapshot paths are client errors, not 500s. */
export class InvalidVersionPathError extends Error {
  constructor() {
    super('版本 ID 或路径无效')
    this.name = 'InvalidVersionPathError'
  }
}

/** IDs generated by the snapshot API. Do not decode untrusted IDs a second time. */
export function assertVersionId(id: string, allowCurrent = false): void {
  if (allowCurrent && id === 'current') return
  // JS '$' also matches before a final newline; the trim check closes that gap.
  if (typeof id !== 'string' || id.trim() !== id || !/^v-[0-9]{1,20}$/.test(id)) {
    throw new InvalidVersionPathError()
  }
}

function storePath(directory: string, filename: string): string {
  const root = path.resolve(directory)
  const rootStat = fs.lstatSync(root, { throwIfNoEntry: false })
  if (rootStat && (!rootStat.isDirectory() || rootStat.isSymbolicLink())) {
    throw new InvalidVersionPathError()
  }
  const canonicalRoot = rootStat ? fs.realpathSync(root) : root
  const target = path.resolve(canonicalRoot, filename)
  if (path.dirname(target) !== canonicalRoot) throw new InvalidVersionPathError()
  const stat = fs.lstatSync(target, { throwIfNoEntry: false })
  // Reject even dangling or in-directory links: never follow a snapshot alias.
  if (stat && (stat.isSymbolicLink() || !stat.isFile())) throw new InvalidVersionPathError()
  if (stat && path.dirname(fs.realpathSync(target)) !== canonicalRoot) {
    throw new InvalidVersionPathError()
  }
  return target
}

export function snapshotPath(directory: string, id: string, temporary = false): string {
  assertVersionId(id)
  return storePath(directory, `${id}.json${temporary ? '.tmp' : ''}`)
}

export function versionIndexPath(directory: string): string {
  return storePath(directory, 'index.json')
}
